entries[9036] = { ["name"] = "Magiewiderstandstrank", ["text"] = "Benötigt Stufe 32\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 3 min lang um 50. (1 Min Abklingzeit)" }
entries[9037] = { ["name"] = "Schrifttafel der Waffe des Felsbeißers", ["text"] = "Klassen: Schamane\nBenutzen: Lehrt 'Blitzschlag' (Rang 2).\nSchleudert einen Blitz auf das Ziel und fügt ihm 28 to 33 Naturschaden zu." }
entries[9039] = { ["name"] = "Schrifttafel des Erdschocks", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Totem der Schlange' (Rang 1).\nBeschwört 30 sec lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 9 to 11 Punkt(e) Feuerschaden anrichtet." }
entries[9040] = { ["name"] = "Schrifttafel der Welle der Heilung II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Schmelzschlag' (Rang 1)." }
entries[9041] = { ["name"] = "Schrifttafel des Totems der Erdbindung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Totem der Erdbindung'.\nBeschwört für 45 sec ein Totem der Erdbindung mit 5 Gesundheit zu Füßen des Zaubernden, das das Bewegungstempo von Feinden im Umkreis von 10 Metern verlangsamt." }
entries[9043] = { ["name"] = "Schrifttafel des Totems der Steinklaue", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 1).\nBeschwört für 15 sec ein Totem der Steinklaue mit [50 + floor(Stamina * 0.05)]\nGesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, für 3 sec betäubt werden. Das Totem der Steinklaue beschützt außerdem all Eure Totems, wodurch sie 21 Schaden absorbieren." }
entries[9044] = { ["name"] = "Schrifttafel des Erdschocks II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 1).\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifende 13 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 min lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)" }
