entries[9084] = { ["name"] = "Schrifttafel des Totems des Windzorns", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Kettenblitzschlag' (Rang 1).\nSchleudert einen Blitzschlag auf den Feind, der 200 to 227 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
