entries[9088] = { ["name"] = "Arthas' Gabe", ["text"] = "Benötigt Stufe 38\nBenutzen: Erhöht den Schattenwiderstand um 10. Wenn ein Feind den Benutzer trifft, besteht eine Chance von 30%, dass der angreifende Feind verflucht wird. Der Fluch erhöht 3 min lang den erlittenen Schaden um 8. Hält 30 min lang an. Wächterelixier. (Procchance: 30%) (3 Sek. Abklingzeit)" }
