entries[9188] = { ["name"] = "Schrifttafel des Totems der Verbrennung II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Schmelzschlag' (Rang 4)." }
entries[9189] = { ["name"] = "Shays Glocke", ["text"] = "Questgegenstand\nEinzigartig\nDauer: 15 min (Realzeit)\nBenutzen: Läutet, um Shay zu Euch zurückzurufen. (1 Min Abklingzeit)" }
entries[9190] = { ["name"] = "Zauberfoliant des Feuerbrandes", ["text"] = "Klassen: Hexenmeister\nBenutzen: Lehrt 'Feuerbrand' (Rang 2).\nVerbrennt den Feind und fügt 24 Feuerschaden sowie 15 sec lang insgesamt 40 zusätzlichen Feuerschaden zu." }
entries[9191] = { ["name"] = "Zauberfoliant des Fluchs der Schwäche", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 4\nBenutzen: Lehrt 'Fluch der Sprachen' (Rang 1).\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 25%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 sec lang an." }
entries[9192] = { ["name"] = "Zauberfoliant der Verderbnis", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 4\nBenutzen: Lehrt 'Verderbnis' (Rang 1).\nVerdirbt das Ziel und verursacht 12 sec lang insgesamt 40 Schattenschaden." }
entries[9193] = { ["name"] = "Zauberfoliant des Aderlasses", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 6\nBenutzen: Lehrt 'Schattenblitz' (Rang 2).\nSendet einen schattigen Blitz zum Gegner, der 26 to 32 Schattenschaden verursacht." }
entries[9194] = { ["name"] = "Zauberfoliant des Fluchs der Pein", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 8\nBenutzen: Lehrt 'Fluch der Pein' (Rang 1).\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 84 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[9195] = { ["name"] = "Zauberfoliant des Seelenabziehens", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 10\nBenutzen: Lehrt 'Furcht' (Rang 1).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 10 sec lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[9197] = { ["name"] = "Elixier der Traumvision", ["text"] = "Benötigt Stufe 38\nBenutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)" }
entries[9198] = { ["name"] = "Zauberfoliant der Lebenslinie", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Lebenslinie' (Rang 1).\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 12 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[9199] = { ["name"] = "Zauberfoliant des Fluchs der Tollkühnheit", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Lebenslinie' (Rang 1).\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 12 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[9200] = { ["name"] = "Zauberfoliant des Fluchs der Schwäche II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Blutsauger' (Rang 1).\nÜberträgt alle 1 Sek. 10 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
entries[9201] = { ["name"] = "Zauberfoliant der Verderbnis II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 16\nBenutzen: Lehrt 'Verderbnis' (Rang 2).\nVerdirbt das Ziel und verursacht 15 sec lang insgesamt 90 Schattenschaden." }
entries[9202] = { ["name"] = "Zauberfoliant des Aderlasses II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 18\nBenutzen: Lehrt 'Seelenstein herstellen'.\nLässt einen schwachen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 400 Gesundheit und 700 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nSchwacher Seelenstein\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Speichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es sich mit 400 Gesundheit und 700 Mana wiederbeleben.\nBenötigt Seelensplitter" }
entries[9203] = { ["name"] = "Zauberfoliant des Rituals der Beschwörung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Feuerregen' (Rang 1).\nLässt einen feurigen Regen niedergehen, der 8 sec lang Feinde im Wirkungsbereich mit insgesamt ( 62 * 4) Feuerschaden verbrennt." }
entries[9204] = { ["name"] = "Zauberfoliant der Lebenslinie II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Feuerregen' (Rang 1).\nLässt einen feurigen Regen niedergehen, der 8 sec lang Feinde im Wirkungsbereich mit insgesamt ( 62 * 4) Feuerschaden verbrennt." }
