entries[9211] = { ["name"] = "Zauberfoliant des Fluchs der Tollkühnheit II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 26\nBenutzen: Lehrt 'Mana entziehen' (Rang 1).\nÜberträgt alle 1 Sek. 3% des Manas des Ziels auf den Zaubernden (bis zu höchstens 6% des maximalen Manas des Zaubernden). Hält 5 sec lang an." }
entries[9212] = { ["name"] = "Zauberfoliant des Schattenblitzes V", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 28\nBenutzen: Lehrt 'Schattenblitz' (Rang 4).\nSendet einen schattigen Blitz zum Gegner, der 92 to 104 Schattenschaden verursacht." }
entries[9214] = { ["name"] = "Zauberfoliant des Infernos", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenötigt Stufe 50\nBenutzen: Lehrt 'Inferno'.\nBeschwört einen Meteor aus dem wirbelnden Nether, der 200 Feuerschaden verursacht und alle feindlichen Ziele in dem Gebiet 2 sec lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 1 min lang unter dem Befehl des Zaubernden steht." }
