entries[9293] = { ["name"] = "Rezept: Magiewiderstandstrank", ["text"] = "Benötigt Alchemie\n(210)\nBenutzen: Lehrt Euch die Herstellung eines Magiewiderstandstranks.\nMagiewiderstandstrank\nBenötigt Stufe 32\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 3 min lang um 50. (1 Min Abklingzeit)\nBenötigt Khadgars Schnurrbart , Lila Lotus , Kristallphiole" }
entries[9294] = { ["name"] = "Rezept: Wildrankentrank", ["text"] = "Benötigt Alchemie\n(225)\nBenutzen: Lehrt Euch die Herstellung eines Wildrankentranks.\nWildrankentrank\nBenötigt Stufe 35\nBenutzen: Stellt 1 to 1500 Gesundheit und 1 to 1500 Mana wieder her. (1 Min Abklingzeit)\nBenötigt Wildranke , Lila Lotus , Kristallphiole" }
entries[9295] = { ["name"] = "Rezept: Unsichtbarkeitstrank", ["text"] = "Benötigt Alchemie\n(235)\nBenutzen: Lehrt Euch die Herstellung eines Unsichtbarkeitstranks.\nUnsichtbarkeitstrank\nBenötigt Stufe 37\nBenutzen: Gewährt dem Anwender 18 sec lang Unsichtbarkeit. (10 Min Abklingzeit)\nBenötigt Geisterpilz , Sonnengras , Kristallphiole" }
entries[9296] = { ["name"] = "Rezept: Arthas' Gabe", ["text"] = "Benötigt Alchemie\n(240)\nBenutzen: Lehrt Euch die Herstellung von Arthas' Gabe.\nArthas' Gabe\nBenötigt Stufe 38\nBenutzen: Erhöht den Schattenwiderstand um 10. Wenn ein Feind den Benutzer trifft, besteht eine Chance von 30%, dass der angreifende Feind verflucht wird. Der Fluch erhöht 3 min lang den erlittenen Schaden um 8. Hält 30 min lang an. Wächterelixier. (Procchance: 30%) (3 Sek. Abklingzeit)\nBenötigt Arthas' Tränen , Blindkraut , Kristallphiole" }
entries[9297] = { ["name"] = "Rezept: Elixier der Traumvision", ["text"] = "Benötigt Alchemie\n(240)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der Traumvision.\nElixier der Traumvision\nBenötigt Stufe 38\nBenutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)\nBenötigt Lila Lotus (3), Kristallphiole" }
entries[9298] = { ["name"] = "Rezept: Elixier der Riesen", ["text"] = "Benötigt Alchemie\n(245)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der Riesen.\nElixier der Riesen\nBenötigt Stufe 38\nBenutzen: Erhöht Eure Stärke 1 hour lang um 25. Kampfelixier. (3 Sek. Abklingzeit)\nBenötigt Sonnengras , Gromsblut , Kristallphiole" }
